public fun DoubleArray.shuffle() { shuffle(Random.Default) }
public fun DoubleArray.shuffle(random: Random) {
    var i = size - 1
    while (i >= 1) {
        val j = random.nextInt(i + 1)
        val t = this[i]
        this[i] = this[j]
        this[j] = t
        i--
    }
}

public fun DoubleArray.reverse(fromIndex: Int, toIndex: Int) {
    checkArrayRangeIndexes(fromIndex, toIndex, size)
    val midPoint = (fromIndex + toIndex) / 2
    if (fromIndex == midPoint) return
    var reverseIndex = toIndex - 1
    var index = fromIndex
    while (index < midPoint) {
        val tmp = this[index]
        this[index] = this[reverseIndex]
        this[reverseIndex] = tmp
        reverseIndex--
        index++
    }
}

